// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }

    function testFuzz_property(uint256 amount, uint256 topUp) public {
        // Admissible domain: a huge initial deposit and any follow-up deposit.
        amount = bound(amount, 2 ** 255, type(uint256).max);
        topUp = bound(topUp, 1, 2 ** 255);

        address actor = address(uint160(uint256(keccak256(abi.encode(amount, topUp)))));

        // 1. deposit `amount`
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // 2. withdraw the entire credited balance
        vm.prank(actor);
        c.withdraw(amount);

        // Rule: once the credited balance is back to zero, ANY follow-up deposit succeeds.
        // In the correct contract balances[actor] == 0 after the withdrawal, so the deposit
        // assert cannot overflow. In the mutant the decrement is missing, so balances[actor]
        // still equals `amount`, and depositing `topUp` overflows the assert and reverts.
        vm.deal(actor, topUp);
        bool ok;
        vm.prank(actor);
        (ok,) = address(c).call{value: topUp}(
            abi.encodeWithSelector(c.deposit.selector)
        );
        assertTrue(ok, "deposit after full withdrawal must succeed");
    }
}
